            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { PaymentSheetEventsEnum, Stripe } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe'</span><span style=\"color:#E1E4E8\">;</span>",
            "",
            "<span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(PaymentSheetEventsEnum.Completed, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'PaymentSheetEventsEnum.Completed'</span><span style=\"color:#E1E4E8\">);</span>",
