            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/your-intent-endpoint'</span><span style=\"color:#E1E4E8\">, {</span>",
            "<span style=\"color:#E1E4E8\">    method: </span><span style=\"color:#9ECBFF\">'POST'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "<span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">response.ok) {</span>",
            "<span style=\"color:#F97583\">    throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`Intent request failed: ${</span><span style=\"color:#E1E4E8\">response</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">status</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#E1E4E8\">  }</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">paymentIntent</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">ephemeralKey</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">customer</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> response.</span><span style=\"color:#B392F0\">json</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#F97583\">as</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#FFAB70\">    paymentIntent</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#FFAB70\">    ephemeralKey</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#FFAB70\">    customer</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#E1E4E8\">  };</span>",
            "",
            "<span style=\"color:#a0aab5\">  // prepare PaymentSheet with CreatePaymentSheetOption.</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">createPaymentSheet</span><span style=\"color:#E1E4E8\">({</span>",
